<template><section class="admin-page"><AdminNav /><div class="page-head"><div><p class="eyebrow">Administration</p><h1>Good day, administrator.</h1><p>Here is your CleanSpaces operations snapshot.</p></div><router-link to="/admin/zones" class="cta">Review zones</router-link></div><p v-if="error" class="error">{{ error }}</p><div class="metric-grid"><article v-for="item in cards" :key="item.label" class="metric"><span>{{ item.icon }}</span><p>{{ item.label }}</p><strong>{{ item.value }}</strong></article></div><section class="quick"><h2>Manage operations</h2><div><router-link to="/admin/zones">Zone approvals <small>Review registrations</small></router-link><router-link to="/admin/employees">Crew members <small>Add and assign your team</small></router-link><router-link to="/admin/payroll">Payroll <small>Record wage payments</small></router-link><router-link to="/admin/cleanup-reports">Cleanup reports <small>Share photo proof</small></router-link></div></section></section></template>
<script setup>
import { computed, onMounted, ref } from 'vue'; import api from '../../api.js'; import AdminNav from './AdminNav.vue'
const data=ref({pending_zones:0,active_zones:0,employees:0,monthly_income:0}),error=ref('');const cards=computed(()=>[{label:'Pending zones',value:data.value.pending_zones,icon:'◷'},{label:'Active zones',value:data.value.active_zones,icon:'⌂'},{label:'Active crew',value:data.value.employees,icon:'♟'},{label:'Monthly income',value:`R${Number(data.value.monthly_income).toLocaleString('en-ZA',{minimumFractionDigits:2})}`,icon:'R'}]);onMounted(async()=>{try{data.value=(await api.get('/admin/dashboard')).data}catch(e){error.value=e.response?.data?.message||'Unable to load dashboard statistics.'}})
</script>
<style scoped>.admin-page{width:min(1120px,100%);margin:auto;padding:2rem 1.5rem 4rem}.page-head{display:flex;justify-content:space-between;align-items:end;gap:1rem;margin:2rem 0}.eyebrow{color:var(--green);font-weight:800;text-transform:uppercase;letter-spacing:.1em;font-size:.75rem;margin:0}.page-head h1{color:var(--green-dark);margin:.2rem 0}.page-head p:not(.eyebrow){margin:0;color:var(--text-muted)}.cta{background:var(--green);color:var(--green-deeper);padding:.65rem 1rem;border-radius:8px;font-weight:800;text-decoration:none}.metric-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1rem}.metric{background:#fff;padding:1.4rem;border-radius:12px;border:1px solid var(--border)}.metric span{color:var(--green);font-weight:900;font-size:1.3rem}.metric p{color:var(--text-muted);margin:.6rem 0 .2rem}.metric strong{font-size:1.55rem;color:var(--green-dark)}.quick{margin-top:2rem;background:var(--green-dark);color:#fff;padding:1.5rem;border-radius:12px}.quick h2{margin-top:0}.quick>div{display:grid;grid-template-columns:repeat(4,1fr);gap:.75rem}.quick a{background:rgba(255,255,255,.08);padding:1rem;border-radius:8px;color:#fff;text-decoration:none;font-weight:700}.quick small{display:block;color:#b9c8c4;font-weight:400;margin-top:.3rem}.error{color:#a32626}@media(max-width:800px){.metric-grid,.quick>div{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.page-head{align-items:start;flex-direction:column}.metric-grid,.quick>div{grid-template-columns:1fr}}</style>
